requests.testScript:
pw.test("Status Code é 200", () => {
  pw.expect(pw.response.status).toBe(200);
});

pw.test("Resposta deve ser uma lista", () => {
  pw.expect(pw.response.body).toBeType("array");
});

pw.test("Status Code é 200 ou 201", () => {
  pw.expect([200, 201]).toInclude(pw.response.status);
});

pw.test("Resposta deve confirmar cadastro", () => {
  pw.expect(pw.response.body).toBeDefined();
});

pw.test("Status Code deve indicar erro ou validação", () => {
  pw.expect([400, 422, 500]).toInclude(pw.response.status);
});
